const FOOD_GENERIC_CAUTIONS = new Set(["因人而异，消化弱者适量；过敏或慢病用药期请咨询医生。", "请结合份量、加工方式与个人耐受综合判断；传统食性不替代现代医学结论。", "结合剂量、加工方式和个人状态综合判断。"]);

function cleanFoodNature(nature) {
  const n = String(nature || "平").trim();
  return ["寒", "凉", "平", "温", "热"].includes(n) ? n : "平";
}

function isGenericFoodCaution(caution) {
  const text = String(caution || "").trim();
  return !text || FOOD_GENERIC_CAUTIONS.has(text);
}

function resolveFoodClassicSources(food) {
  if (Array.isArray(food.sources) && food.sources.length) {
    return food.sources.filter((s) => s?.title && s.title !== "地域食疗整理");
  }
  const byId = FOOD_CLASSIC_LOOKUP.byId[food.id];
  if (byId?.length) return byId;
  const byName = FOOD_CLASSIC_LOOKUP.byName[food.name];
  if (byName?.length) return byName;
  for (const alias of food.aliases || []) {
    if (FOOD_CLASSIC_LOOKUP.byName[alias]?.length) return FOOD_CLASSIC_LOOKUP.byName[alias];
  }
  const category = FOOD_CLASSIC_LOOKUP.categoryFallback[food.category];
  if (category?.length) return category;
  return FOOD_CLASSIC_LOOKUP.natureFallback[food.nature] || FOOD_CLASSIC_LOOKUP.natureFallback.平;
}

function deriveFoodEatingGuide(food) {
  const nature = cleanFoodNature(food.nature);
  const category = food.category || "蔬菜";
  const name = food.name || "该食材";
  const effect = (food.effects || [])[0] || "";
  const introRaw = String(food.summary || "").replace(/\s+/g, "").trim();
  const intro = introRaw ? (introRaw.length <= 48 ? introRaw : introRaw.slice(0, 48) + "…") : (FOOD_EATING_CATEGORY_INTRO[category] || "按家常饮食适量食用。");
  const pairBase = FOOD_EATING_CATEGORY_PAIR[category] || "与主食、蛋白、蔬菜一起看整体饮食结构。";
  let alone = FOOD_EATING_NATURE_ALONE[nature];
  if (category === "调料" || category === "茶饮") {
    alone = name + "偏" + nature + "，宜少量" + (category === "调料" ? "调味" : "冲泡") + "，不宜大量单独食用。";
  } else if (category === "水果") {
    alone = name + "作水果" + (nature === "寒" || nature === "凉" ? "偏清凉" : "偏平和") + "，餐间少量即可，不宜代餐。";
  } else if (food.officialFoodMedicine) {
    alone = name + "属药食同源目录，宜少量入粥汤茶饮，不宜长期大量当普通蔬菜吃。";
  }
  let timing = FOOD_EATING_NATURE_TIMING[nature];
  if (effect.includes("湿") || effect.includes("利")) timing = "身重困倦、小便不利、暑湿偏重时更适宜；阳虚怕冷、孕妇等特殊人群慎用。";
  else if (effect.includes("润") || effect.includes("阴")) timing = "秋燥口干、咽干皮肤干时更适宜；腹泻便溏、痰多体腻时减量。";
  else if (effect.includes("温") || effect.includes("补")) timing = "畏寒乏力、病后恢复、冬季进补时更适宜；实热上火时不宜。";
  let pair = pairBase;
  if (nature === "寒" || nature === "凉") pair = "偏寒凉，" + pairBase + " 可配姜葱、胡椒等温性配料平衡。";
  else if (nature === "温" || nature === "热") pair = "偏温热，" + pairBase + " 宜配清淡蔬菜，避免与大量辛辣烧烤同餐。";
  let caution = FOOD_EATING_NATURE_CAUTION[nature];
  if (food.caution && !isGenericFoodCaution(food.caution)) caution = food.caution;
  else if (category === "海产") caution = "海鲜过敏、痛风急性期、甲状腺特殊疾病者需注意；必须彻底煮熟。";
  else if (category === "腌菜") caution = "钠含量高，高血压、肾病水肿者严控份量。";
  else if (category === "菌菇") caution = "须彻底煮熟；菌菇过敏、痛风急性期不宜大量浓汤。";
  else if (food.officialFoodMedicine) caution = "药食同源不等于人人适宜，孕妇、慢病用药期请咨询医生。";
  const natureNote = (food.natureConfidence === "low" || food.natureSource === "category-default")
    ? "食性按品类与名称规则整理，供日常参考，不替代个体化辨证。"
    : "";
  return { eatingIntro: name + "：" + intro, alone, timing, pair, caution, natureNote };
}

function enrichFoodContent(food) {
  const guide = deriveFoodEatingGuide(food);
  const sources = resolveFoodClassicSources(food);
  return {
    ...food,
    alone: food.alone || guide.alone,
    timing: food.timing || guide.timing,
    pair: food.pair || guide.pair,
    caution: isGenericFoodCaution(food.caution) ? guide.caution : food.caution,
    eatingIntro: food.eatingIntro || guide.eatingIntro,
    natureNote: food.natureNote || guide.natureNote || "",
    sources: food.sources?.length ? food.sources.filter((s) => s?.title !== "地域食疗整理") : sources
  };
}
